True def transform(grid):
    out = [row[:] for row in grid]
    heights = {2: 4, 8: 3}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color in heights:
                height = heights[color]
                for offset in range(1, height + 1):
                    rr = r - offset
                    if rr < 0:
                        break
                    out[rr][c] = color if offset == height else 1
    return out
